  "python_code": "import os
import json
from pathlib import Path
from typing import Dict


def run(config: dict, project_root: Path) -> dict:
    try:
        input_directory = config['paths']['input_directory']
        output_directory = config['paths']['output_directory']
        line_counts = {}

        # 获取所有 txt 文件
        txt_files = list(Path(input_directory).glob('*.txt'))
        if not txt_files:
            return {'success': False, 'message': '未找到任何 txt 文件。', 'output_files': []}

        # 统计每个文件的行数
        for txt_file in txt_files:
            with open(txt_file, 'r') as file:
                line_count = sum(1 for _ in file)
                line_counts[txt_file.name] = line_count

        # 将结果写入 JSON 文件
        output_file = Path(output_directory) / 'line_counts.json'
        with open(output_file, 'w') as json_file:
            json.dump(line_counts, json_file)

        return {'success': True, 'message': '行数统计成功。', 'output_files': [str(output_file)]}
    except Exception as e:
        return {'success': False, 'message': str(e), 'output_files': []}",
